// ドット絵を画像（data URL）にする。大きく出すときは CSS の image-rendering: pixelated で
const cache = {};
// 配合限定の 子で 絵が まだ ない とき：「？」の たまご（絵は モデリング専用スレッドに 頼む）
const EGG = (() => {
  const Q = ["..XX..", ".X..X.", "....X.", "...X..", "...X..", "......", "...X.."];   // 「？」6×7
  const px = Array.from({ length: 24 }, (_, y) => Array.from({ length: 24 }, (_, x) => {
    const ry = y < 13 ? 10 : 8.5, rx = 7.5 * Math.sqrt(Math.max(0, 1 - ((y - 13) / ry) ** 2)) * (y < 13 ? 0.92 + 0.08 * (y / 13) : 1);
    return Math.abs(x - 11.5) <= rx ? 1 : 0; }));
  return { pal: ["#7C88A3", "#C9D3E6", "#FFFFFF", "#5F6B86"], px: px.map((row, y) => row.map((v, x) => {
    if (!v) return ".";
    if (!(px[y - 1] || [])[x] || !(px[y + 1] || [])[x] || !row[x - 1] || !row[x + 1]) return "a";   // ふち
    const qy = y - 9, qx = x - 9; if (qy >= 0 && qy < 7 && qx >= 0 && qx < 6 && Q[qy][qx] === "X") return "d";
    return (x - 8) ** 2 + (y - 7) ** 2 < 3 ? "c" : "b";
  }).join("")) };
})();
export function spriteURL(id) {
  if (cache[id]) return cache[id];
  if (!SPRITES[id] && /_ev$/.test(id)) return spriteURL(id.slice(0, -3));   // 進化した 敵の ツリー（＋）は もとの 敵の 絵
  const s = SPRITES[id] || (/^(f_|e3_)/.test(id) ? EGG : null); if (!s) return "";   // 絵が まだ ない 配合限定と ミカネル島の 敵は「？の たまご」
  const cv = document.createElement("canvas"); cv.width = cv.height = 24;
  const cx = cv.getContext("2d");
  s.px.forEach((row, y) => [...row].forEach((ch, x) => { if (ch !== ".") { cx.fillStyle = s.pal["abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".indexOf(ch)]; cx.fillRect(x, y, 1, 1); } }));
  return (cache[id] = cv.toDataURL());
}
